/**
 * Sidebar music player. Plays the mp3 tracks emitted at build time as
 * ./assets/music/playlist.json (generated by build.sh from
 * static/assets/music/*.mp3).
 */
document.addEventListener('DOMContentLoaded', () => {
  const musicToggle = document.getElementById('music-toggle');
  const musicFloating = document.getElementById('music-floating');

  if (musicToggle && musicFloating) {
    function setPlayerVisible(visible) {
      if (visible) musicFloating.removeAttribute('hidden');
      else musicFloating.setAttribute('hidden', '');
      musicToggle.classList.toggle('active', visible);
    }

    musicToggle.addEventListener('click', () => {
      setPlayerVisible(musicFloating.hasAttribute('hidden'));
    });

    musicToggle.addEventListener('mouseenter', () => {
      setPlayerVisible(true);
    });

    musicFloating.addEventListener('mouseleave', () => {
      setPlayerVisible(false);
    });
  }

  const player = document.getElementById('music-player');
  if (!player) return;

  const audio = document.getElementById('player-audio');
  const titleEl = document.getElementById('player-title');
  const artistEl = document.getElementById('player-artist');
  const creditEl = document.getElementById('player-credit');
  const timeEl = document.getElementById('player-time');
  const progressEl = document.getElementById('player-progress');
  const progressBar = document.getElementById('player-progress-bar');
  const shuffleBtn = document.getElementById('player-shuffle');
  const prevBtn = document.getElementById('player-prev');
  const toggleBtn = document.getElementById('player-toggle');
  const nextBtn = document.getElementById('player-next');
  const repeatBtn = document.getElementById('player-repeat');
  const playerIconPlay = toggleBtn.querySelector('.icon-play');
  const playerIconPause = toggleBtn.querySelector('.icon-pause');
  const volumeEl = document.getElementById('player-volume');
  const volumeLabel = document.getElementById('player-volume-label');
  const volumeTrack = document.getElementById('player-volume-track');
  const plistBtn = document.getElementById('player-plist-btn');
  const plistEl = document.getElementById('player-plist');
  const autoplayNote = document.getElementById('player-autoplay');

  let tracks = [];
  let current = 0;
  let shuffle = false;
  let repeat = false;
  let plistVisible = false;
  let resumeTime = 0;

  const LS_CURRENT = 'newspaper-music-current';
  const LS_TIME = 'newspaper-music-time';
  const LS_PLAYING = 'newspaper-music-playing';

  function fmt(t) {
    if (!isFinite(t) || isNaN(t)) return '0:00';
    const m = Math.floor(t / 60);
    const s = Math.floor(t % 60);
    return `${m}:${String(s).padStart(2, '0')}`;
  }

  function renderPlist() {
    plistEl.innerHTML = '';
    tracks.forEach((track, i) => {
      const li = document.createElement('li');
      li.textContent = `${i + 1}. ${track.title}`;
      if (track.artist) {
        const span = document.createElement('span');
        span.textContent = ` · ${track.artist}`;
        li.appendChild(span);
      }
      li.addEventListener('click', () => {
        current = i;
        play();
      });
      plistEl.appendChild(li);
    });
  }

  function setTrackInfo() {
    const isPt = (localStorage.getItem('newspaper-lang') || 'en') === 'pt';
    const track = tracks[current] || {};
    titleEl.textContent = track.title || '—';
    if (artistEl) artistEl.textContent = track.artist ? (isPt ? `por ${track.artist}` : `by ${track.artist}`) : '';
    const artist = track.artist || '';
    if (creditEl) {
      const link = '<a href="https://github.com/gabrielzschmitz/gabrielzschmitz-website/tree/main/static/assets/music/ATTRIBUTION.md">' +
        (isPt ? 'atribuição' : 'attribution') + '</a>';
      creditEl.innerHTML = isPt
        ? `Música por ${artist} — reproduzida com ${link}.`
        : `Song by ${artist} — reproduced with ${link}.`;
    }
  }

  function setPlayIcon(playing) {
    if (playerIconPlay) {
      if (playing) playerIconPlay.setAttribute('hidden', '');
      else playerIconPlay.removeAttribute('hidden');
    }
    if (playerIconPause) {
      if (!playing) playerIconPause.setAttribute('hidden', '');
      else playerIconPause.removeAttribute('hidden');
    }
    toggleBtn.setAttribute('title', playing ? 'Pause' : 'Play');
    toggleBtn.setAttribute('aria-label', playing ? 'Pause' : 'Play');
  }

  function setPlistLabel() {
    const isPt = (localStorage.getItem('newspaper-lang') || 'en') === 'pt';
    plistBtn.textContent = `${isPt ? 'Lista de faixas' : 'Track list'} ${plistVisible ? '▴' : '▾'}`;
  }

  function play() {
    if (!tracks.length) return;
    audio.src = tracks[current].src;
    setTrackInfo();
    localStorage.setItem(LS_CURRENT, String(current));
    audio.play().catch((err) => { if (isAutoplayError(err)) renderAutoplayBlocked(); });
  }

  function persistTime() {
    if (isFinite(audio.duration) && audio.duration > 0 && audio.currentTime > 0) {
      localStorage.setItem(LS_TIME, String(audio.currentTime));
    }
  }

  let seeking = false;

  function updateTime() {
    if (seeking) return;
    if (!isFinite(audio.duration)) {
      timeEl.textContent = `${fmt(audio.currentTime)} / 0:00`;
    } else {
      timeEl.textContent = `${fmt(audio.currentTime)} / ${fmt(audio.duration)}`;
    }
    const pct = audio.duration ? (audio.currentTime / audio.duration) * 100 : 0;
    progressBar.style.width = `${pct}%`;
  }

  function seekTo(x) {
    if (!isFinite(audio.duration)) return;
    const rect = progressEl.getBoundingClientRect();
    let t = (x - rect.left) / rect.width;
    t = Math.max(0, Math.min(1, t));
    audio.currentTime = t * audio.duration;
    progressBar.style.width = `${t * 100}%`;
  }

  function pickNext() {
    if (shuffle && tracks.length > 1) {
      let next;
      do { next = Math.floor(Math.random() * tracks.length); }
      while (next === current);
      current = next;
    } else if (current < tracks.length - 1) {
      current += 1;
    } else {
      current = 0;
    }
  }

  let resumeArmed = true;
  let autoplayBlocked = false;

  function isAutoplayError(err) {
    return !!err && (err.name === 'NotAllowedError' || err.name === 'AbortError');
  }

  function autoplayGuidanceHtml() {
    const isPt = (localStorage.getItem('newspaper-lang') || 'en') === 'pt';
    const ua = navigator.userAgent;
    let steps;
    if (/Firefox\//.test(ua) && !/Seamonkey\//.test(ua)) {
      steps = isPt
        ? 'Menu Firefox → Configurações → Privacidade e segurança → Reprodução automática → Padrão: Permitir áudio e vídeo.'
        : 'Firefox menu → Settings → Privacy & Security → Autoplay → Default: Allow audio and video.';
    } else if (/Chrome\//.test(ua) || /Chromium\//.test(ua) || /Edge\//.test(ua)) {
      steps = isPt
        ? 'Configurações do site → Som → Reprodução automática → Permitir.'
        : 'Site settings → Sound → Autoplay → Allow.';
    } else {
      steps = isPt
        ? 'Configurações → Sites → Reprodução automática → Permitir tudo para este site.'
        : 'Settings → Websites → Auto-Play → Allow All Auto-Play for this site.';
    }
    const heading = isPt
      ? 'Reprodução automática bloqueada. Para permitir:'
      : 'Autoplay is blocked. To allow it:';
    return '<span class="player-autoplay-head">' + heading + '</span>' +
      '<span class="player-autoplay-steps">' + steps + '</span>';
  }

  function renderAutoplayBlocked() {
    if (!autoplayNote) return;
    autoplayBlocked = true;
    autoplayNote.removeAttribute('data-en');
    autoplayNote.removeAttribute('data-pt');
    autoplayNote.classList.add('guide');
    autoplayNote.innerHTML = autoplayGuidanceHtml();
    autoplayNote.removeAttribute('hidden');
  }

  function resumePlayback() {
    if (!resumeArmed) return;
    if (!audio.src || !tracks.length) return;
    audio.play()
      .then(() => { resumeArmed = false; })
      .catch((err) => { if (isAutoplayError(err)) renderAutoplayBlocked(); });
  }

  ['pointerdown', 'keydown', 'touchstart'].forEach(type => {
    document.addEventListener(type, (e) => {
      if (autoplayNote && e.target && e.target.closest && e.target.closest('#player-autoplay')) return;
      resumePlayback();
    }, { once: false, passive: true });
  });

  fetch('/assets/music/playlist.json')
    .then(r => r.json())
    .then(list => {
      tracks = list.tracks || list;
      renderPlist();

      const skey = localStorage.getItem('newspaper-music-shuffle') === '1';
      shuffle = skey;
      shuffleBtn.classList.toggle('active', shuffle);
      const rkey = localStorage.getItem('newspaper-music-repeat') === '1';
      repeat = rkey;
      repeatBtn.classList.toggle('active', repeat);

      const savedIdx = parseInt(localStorage.getItem(LS_CURRENT), 10);
      if (Number.isInteger(savedIdx) && savedIdx >= 0 && savedIdx < tracks.length) {
        current = savedIdx;
      } else {
        const defaultIdx = tracks.findIndex(t =>
          decodeURIComponent(t.src.split('/').pop()) === (list.default || '')
        );
        current = defaultIdx >= 0 ? defaultIdx : 0;
      }
      const savedTime = parseFloat(localStorage.getItem(LS_TIME));
      if (Number.isFinite(savedTime) && savedTime > 0) {
        resumeTime = savedTime;
      }

      audio.src = tracks[current].src;
      setTrackInfo();

      resumeArmed = localStorage.getItem(LS_PLAYING) === '1';
      if (resumeArmed) {
        resumePlayback();
      }
    })
    .catch(() => {
      plistBtn.disabled = true;
    });

  toggleBtn.addEventListener('click', () => {
    if (!tracks.length) return;
    if (audio.paused) {
      if (!audio.src) {
        play();
      } else {
        audio.play().catch((err) => { if (isAutoplayError(err)) renderAutoplayBlocked(); });
      }
    } else {
      audio.pause();
    }
  });

  nextBtn.addEventListener('click', () => {
    if (!tracks.length) return;
    pickNext();
    play();
  });

  prevBtn.addEventListener('click', () => {
    if (!tracks.length) return;
    if (audio.currentTime > 3) {
      audio.currentTime = 0;
      return;
    }
    current = current > 0 ? current - 1 : tracks.length - 1;
    play();
  });

  shuffleBtn.addEventListener('click', () => {
    shuffle = !shuffle;
    shuffleBtn.classList.toggle('active', shuffle);
    localStorage.setItem('newspaper-music-shuffle', shuffle ? '1' : '0');
  });

  repeatBtn.addEventListener('click', () => {
    repeat = !repeat;
    repeatBtn.classList.toggle('active', repeat);
    localStorage.setItem('newspaper-music-repeat', repeat ? '1' : '0');
  });

  function seekStart(e) {
    if (!isFinite(audio.duration)) return;
    seeking = true;
    e.preventDefault();
    progressEl.setPointerCapture(e.pointerId);
    seekTo(e.clientX);
  }

  function seekMove(e) {
    if (!seeking) return;
    seekTo(e.clientX);
  }

  function seekEnd() {
    seeking = false;
  }

  progressEl.addEventListener('pointerdown', seekStart);
  progressEl.addEventListener('pointermove', seekMove);
  progressEl.addEventListener('pointerup', seekEnd);
  progressEl.addEventListener('pointercancel', seekEnd);

  function updateVolume() {
    const v = volumeEl.value;
    audio.volume = v / 100;
    volumeLabel.textContent = `${v}%`;
    const vpct = `${v}%`;
    volumeEl.style.setProperty('--vol', vpct);
    if (volumeTrack) volumeTrack.style.setProperty('--vol', vpct);
  }

  function volumeFromX(x) {
    const rect = volumeEl.getBoundingClientRect();
    let t = (x - rect.left) / rect.width;
    t = Math.max(0, Math.min(1, t));
    const v = Math.round(t * 100);
    volumeEl.value = v;
    updateVolume();
    localStorage.setItem('newspaper-music-volume', String(v));
  }

  volumeEl.addEventListener('input', () => {
    updateVolume();
    localStorage.setItem('newspaper-music-volume', volumeEl.value);
  });

  volumeEl.addEventListener('pointerdown', (e) => {
    e.preventDefault();
    volumeEl.setPointerCapture(e.pointerId);
    volumeFromX(e.clientX);
  });

  volumeEl.addEventListener('pointermove', (e) => {
    if (!volumeEl.hasPointerCapture(e.pointerId)) return;
    volumeFromX(e.clientX);
  });

  plistBtn.addEventListener('click', () => {
    plistVisible = !plistVisible;
    plistEl.hidden = !plistVisible;
    setPlistLabel();
  });

  document.addEventListener('languagechange', (e) => {
    setPlistLabel();
    setTrackInfo();
    if (autoplayBlocked) renderAutoplayBlocked();
  });

  setPlistLabel();
  setTrackInfo();

  audio.addEventListener('timeupdate', () => {
    updateTime();
    persistTime();
  });
  audio.addEventListener('loadedmetadata', () => {
    updateTime();
    if (resumeTime > 0 && isFinite(audio.duration) && resumeTime < audio.duration) {
      audio.currentTime = resumeTime;
    }
    resumeTime = 0;
  });
  audio.addEventListener('seeked', persistTime);
  audio.addEventListener('play', () => {
    setPlayIcon(true);
    localStorage.setItem(LS_PLAYING, '1');
  });
  audio.addEventListener('pause', () => {
    setPlayIcon(false);
    localStorage.setItem(LS_PLAYING, '0');
  });
  audio.addEventListener('ended', () => {
    setPlayIcon(false);
    localStorage.removeItem(LS_TIME);
    if (repeat) {
      audio.currentTime = 0;
      audio.play().catch((err) => { if (isAutoplayError(err)) renderAutoplayBlocked(); });
    } else {
      pickNext();
      play();
    }
  });

  const stored = localStorage.getItem('newspaper-music-volume');
  if (stored !== null) {
    volumeEl.value = stored;
  }
  updateVolume();
});